#!/bin/sh
# G4 measurement driver (plan attach-2026-11 WP-6): what an outside harness holding a viewer's PTY can observe of `cterm attach`.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'scripts/g4/g4.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'g4.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -eu

usage() {
	cat <<'USAGE'
Usage: g4.sh [--help|-h] [--build|--version]
       g4.sh --local [--bin PATH] [OPTIONS] [LEG...]
       g4.sh [--far-bin PATH --far-dir DIR | --session ID [--marker TEXT]] [OPTIONS] TARGET_HOST [LEG...]

Legs (default: first-frame bytes echo stall): first-frame, bytes, echo, stall, summarize (print the table of a run directory).
The harness only watches the viewer's PTY from outside (a perl-base helper, scripts/g4/g4pty.pl, holds the PTY and timestamps with
clock_gettime); the daemon and the client carry no timing hook. Every number it prints from a --local run is indicative.

  first-frame  time from starting `cterm attach` to a marker the session already shows appearing in the viewer's output; with a
               TARGET_HOST the ssh handshake (`ssh -- HOST true`, same run count) is timed beside it; a noise floor (a PTY running
               a plain `sh` that prints the marker, no cterm) is interleaved.
  bytes        bytes on the viewer's output for three workloads (idle shell, scrolling build log, full-screen redraw loop) against
               the bytes the workload wrote to its own PTY (its own count; workload.pl).
  echo         a keystroke written to the viewer's PTY to its echo appearing there: median and p95; a noise floor (a PTY running
               `cat`, no cterm) is interleaved; with a TARGET_HOST the link RTT (ping, else not measured) is recorded beside it.
  stall        viewer A stops reading for 5 s under a flood while viewer B's echo latency is measured (baseline before the flood,
               then during it); then A reads again and the marker the flood ends with must arrive on its screen.

Modes:
  --local             every leg on this host, against a harness daemon the script starts on a scratch runtime directory under
                      $TMPDIR (never the real one). --bin PATH is the cterm to use (default: target/release/cterm, else
                      target/debug/cterm, whichever exists; the choice is printed). The daemon runs with the TEST-ONLY
                      CTERM_DEBUG_DAEMON_HEADLESS=1 and CTERM_DEBUG_HEADLESS_IDENTITY=1 (the mechanism tests/attach_cli.rs uses).
  TARGET_HOST         the gate of record: the viewer (and the PTY holder) run here, the session and the daemon on TARGET_HOST over
                      ssh (BatchMode; never prompts). Two target kinds:
    --far-bin PATH --far-dir DIR   a harness daemon on TARGET_HOST: PATH is the far cterm, DIR a scratch directory the script
                      creates (it must not exist) and removes. Needs perl on TARGET_HOST. All four legs.
    --session ID [--marker TEXT]   the target's live daemon: attach to an existing session ID whose screen shows TEXT (default
                      G4MARK). Only first-frame and an idle-bytes observation run (the other legs type into and flood a session,
                      which a live session must not suffer). `cterm` must be on the far non-interactive PATH (--far-bin overrides).
                      The live daemon must be 0.7.0 or newer; a 0.6.0 daemon does not know attach.

Options: --runs N (first-frame runs, default 15 after 2 warm-up), --echo-runs N (default 6 after 1 warm-up; 20 keystrokes each),
         --bytes-runs N (per workload, default 3), --bytes-secs N (default 12), --stall-runs N (default 3), --out DIR (default
         runs/spike/g4/<timestamp>). Legs run in the order given; rounds interleave the cterm and noise-floor variants, alternating
         which goes first, and rotate the workload order.

Output: raw files <leg>.raw, env.txt (date, versions, run counts, leg order, load and PSI at start and end on both ends, binaries),
rtt.txt and summary.txt in the run directory. Every process the script starts is recorded and ended on every way out; the scratch
directory is removed. Nothing is ever signalled by pattern.
USAGE
}

HERE=$(cd "$(dirname "$0")" && pwd -P)
R=$(cd "$HERE/../.." && pwd -P)
case " $* " in *" --help "* | *" -h "*) usage; exit 0 ;; esac
# shellcheck source-path=SCRIPTDIR source=../lib/build-id.sh
. "$HERE/../lib/build-id.sh"
build_flags "$0" "$@"

die() { printf 'g4.sh: %s\n' "$*" >&2; exit 2; }

MODE=''; BIN=''; FARBIN=''; FARDIR=''; SESSION=''; MARKER='G4MARK'; HOST=''; LEGS=''
RUNS=15; ERUNS=6; BRUNS=3; BSECS=12; SRUNS=3; OUT=''; WARM=2; EWARM=1
while [ "$#" -gt 0 ]; do
	case $1 in
	--local) MODE=local ;;
	--bin) [ "$#" -ge 2 ] || die "--bin needs a path"; BIN=$2; shift ;;
	--far-bin) [ "$#" -ge 2 ] || die "--far-bin needs a path"; FARBIN=$2; shift ;;
	--far-dir) [ "$#" -ge 2 ] || die "--far-dir needs a path"; FARDIR=$2; shift ;;
	--session) [ "$#" -ge 2 ] || die "--session needs an id"; SESSION=$2; shift ;;
	--marker) [ "$#" -ge 2 ] || die "--marker needs a text"; MARKER=$2; shift ;;
	--runs) [ "$#" -ge 2 ] || die "--runs needs a number"; RUNS=$2; shift ;;
	--echo-runs) [ "$#" -ge 2 ] || die "--echo-runs needs a number"; ERUNS=$2; shift ;;
	--bytes-runs) [ "$#" -ge 2 ] || die "--bytes-runs needs a number"; BRUNS=$2; shift ;;
	--bytes-secs) [ "$#" -ge 2 ] || die "--bytes-secs needs a number"; BSECS=$2; shift ;;
	--stall-runs) [ "$#" -ge 2 ] || die "--stall-runs needs a number"; SRUNS=$2; shift ;;
	--out) [ "$#" -ge 2 ] || die "--out needs a directory"; OUT=$2; shift ;;
	first-frame | bytes | echo | stall | summarize) LEGS="$LEGS $1" ;;
	-*) die "unknown option: $1 (see --help)" ;;
	*) [ -z "$HOST" ] || die "second host argument: $1"; HOST=$1 ;;
	esac
	shift
done
for n in "$RUNS" "$ERUNS" "$BRUNS" "$BSECS" "$SRUNS"; do
	case $n in '' | *[!0-9]* | 0) die "a count must be a positive integer, got '$n'" ;; esac
done
[ -n "$LEGS" ] || LEGS=" first-frame bytes echo stall"
if [ "$LEGS" = " summarize" ]; then
	[ -n "$OUT" ] || OUT=$(ls -d "$R"/runs/spike/g4/*/ 2>/dev/null | tail -1)
	[ -d "$OUT" ] || die "no run directory (give --out DIR)"
	perl "$HERE/summarize.pl" "$OUT"
	exit 0
fi

# valid_host as crates/crucible-term/src/cli.rs: [A-Za-z0-9._@-]+, not starting with -.
valid_host() { case $1 in '' | -* | *[!A-Za-z0-9._@-]*) return 1 ;; esac; }
safe_path() { case $1 in '' | *[!A-Za-z0-9._/@+-]*) return 1 ;; esac; }

if [ "$MODE" = local ]; then
	[ -z "$HOST" ] || die "--local and TARGET_HOST are exclusive"
	[ -z "$FARBIN$FARDIR$SESSION" ] || die "--far-bin/--far-dir/--session are for a TARGET_HOST run"
else
	[ -n "$HOST" ] || die "give --local or a TARGET_HOST"
	valid_host "$HOST" || die "bad host '$HOST' (want [A-Za-z0-9._@-]+, not starting with -)"
	MODE=remote
	if [ -n "$SESSION" ]; then
		[ -z "$FARDIR" ] || die "--session and --far-dir are exclusive"
		case $SESSION in '' | *[!0-9A-Fa-f]*) die "bad session '$SESSION'" ;; esac
		[ -n "$FARBIN" ] || FARBIN=cterm
		safe_path "$FARBIN" || die "--far-bin has characters outside [A-Za-z0-9._/@+-]"
	else
		[ -n "$FARBIN" ] && [ -n "$FARDIR" ] || die "a TARGET_HOST run needs --far-bin and --far-dir (harness daemon) or --session (live daemon)"
		safe_path "$FARBIN" && safe_path "$FARDIR" || die "--far-bin/--far-dir have characters outside [A-Za-z0-9._/@+-]"
		case $FARDIR in /*) ;; *) die "--far-dir must be absolute" ;; esac
	fi
fi

if [ "$MODE" = local ] && [ -z "$BIN" ]; then
	if [ -x "$R/target/release/cterm" ]; then BIN=$R/target/release/cterm; elif [ -x "$R/target/debug/cterm" ]; then BIN=$R/target/debug/cterm; else die "no cterm built (target/release or target/debug); pass --bin"; fi
fi
if [ "$MODE" = local ]; then
	[ -x "$BIN" ] || die "--bin $BIN is not executable"
	safe_path "$BIN" || die "--bin has characters outside [A-Za-z0-9._/@+-]"
fi

STAMP=$(date +%Y%m%dT%H%M%S)
[ -n "$OUT" ] || OUT=$R/runs/spike/g4/$STAMP
DPID=''; HPIDS=''; CREATED=''; TD=''

# tx CMD: run a shell command string on the target (ssh in a TARGET_HOST run). Never prompts.
tx() {
	if [ "$MODE" = remote ]; then ssh -o BatchMode=yes -o ConnectTimeout=10 -- "$HOST" "$1" </dev/null; else sh -c "$1" </dev/null; fi
}
# txin CMD: the same, with stdin passed through.
txin() {
	if [ "$MODE" = remote ]; then ssh -o BatchMode=yes -o ConnectTimeout=10 -- "$HOST" "$1"; else sh -c "$1"; fi
}

cleanup() {
	trap - EXIT INT TERM HUP
	exec 3>&- 2>/dev/null || true
	for p in $HPIDS; do kill "$p" 2>/dev/null || true; done
	if [ -n "$DPID" ]; then
		if [ "$MODE" = remote ]; then tx "kill $DPID" 2>/dev/null || true
		elif grep -q daemon "/proc/$DPID/cmdline" 2>/dev/null; then kill "$DPID" 2>/dev/null || true; fi
	fi
	if [ -n "$CREATED" ] && [ -n "$TD" ]; then
		if [ "$MODE" = remote ]; then tx "sleep 1; rm -rf $TD" 2>/dev/null || true; else sleep 1; rm -rf "$TD"; fi
	fi
	[ -z "${FIFO_DIR:-}" ] || rm -rf "$FIFO_DIR"
}
trap cleanup EXIT
trap 'exit 130' INT TERM HUP

ts() { date +%Y-%m-%dT%H:%M:%S; }
cond() { # label: load and PSI on both ends
	printf '%s %s local load=%s psi_cpu=%s\n' "$(ts)" "$1" "$(cut -d' ' -f1-3 /proc/loadavg)" "$(head -1 /proc/pressure/cpu 2>/dev/null || echo n/a)" >>"$OUT/env.txt"
	if [ "$MODE" = remote ]; then
		printf '%s %s target load=%s psi_cpu=%s\n' "$(ts)" "$1" "$(tx 'cut -d" " -f1-3 /proc/loadavg' 2>/dev/null || echo n/a)" "$(tx 'head -1 /proc/pressure/cpu 2>/dev/null || echo n/a' 2>/dev/null || echo n/a)" >>"$OUT/env.txt"
	fi
}

PTYPL=$HERE/g4pty.pl
mkdir -p "$OUT"
if [ -n "$SESSION" ]; then
	for l in $LEGS; do case $l in echo | stall) printf 'g4.sh: leg %s skipped: it types into or floods a session, so it needs a harness daemon (--far-bin/--far-dir)\n' "$l" >&2 ;; esac; done
fi

# Target setup.
if [ "$MODE" = local ]; then
	TD=$(mktemp -d "${TMPDIR:-/tmp}/g4-XXXXXX"); CREATED=1
	TBIN=$BIN; PTY_T=$PTYPL; WL_T=$HERE/workload.pl
else
	TBIN=$FARBIN
	if [ -z "$SESSION" ]; then
		TD=$FARDIR
		tx "mkdir -- $TD" || die "could not create $TD on $HOST (it must not exist)"
		CREATED=1
		txin "cat > $TD/g4pty.pl" <"$PTYPL"; txin "cat > $TD/workload.pl" <"$HERE/workload.pl"
		PTY_T=$TD/g4pty.pl; WL_T=$TD/workload.pl
	fi
fi
if [ -n "$TD" ]; then
	case ${XDG_RUNTIME_DIR:-/nonexistent} in "$TD"/run) die "refusing: the scratch runtime directory is the real one" ;; esac
	TENV="XDG_RUNTIME_DIR=$TD/run XDG_STATE_HOME=$TD/state XDG_CONFIG_HOME=$TD/cfg HOME=$TD/home CTERM_DEBUG_DAEMON_HEADLESS=1 CTERM_DEBUG_HEADLESS_IDENTITY=1"
	tx "mkdir -p $TD/run $TD/state $TD/cfg/crucible-term $TD/home && chmod 700 $TD/run"
	DPID=$(tx "env $TENV $TBIN daemon </dev/null >$TD/daemon.log 2>&1 & echo \$!")
	case $DPID in '' | *[!0-9]*) die "could not start the harness daemon: '$DPID'" ;; esac
	i=0
	until tx "test -S $TD/run/cterm/daemon.sock"; do
		i=$((i + 1)); [ "$i" -le 50 ] || die "harness daemon did not listen (see $TD/daemon.log)"
		sleep 0.2
	done
	TCT="env $TENV $TBIN"
else
	TENV=''
	TCT=$TBIN
fi

FIFO_DIR=$(mktemp -d "${TMPDIR:-/tmp}/g4f-XXXXXX")
cond start
{
	printf 'date %s\nhost %s\nmode %s\n' "$(ts)" "$(hostname -s)" "$MODE"
	printf 'driver build %s\n' "$(build_id "$0")"
	printf 'legs%s\nruns first-frame=%s (+%s warm-up) echo=%s (+%s warm-up, 20 keys each) bytes=%s per workload x %s s stall=%s (5 s stall)\n' "$LEGS" "$RUNS" "$WARM" "$ERUNS" "$EWARM" "$BRUNS" "$BSECS" "$SRUNS"
	printf 'order: legs as listed; each round runs the cterm variant and its noise-floor variant, alternating which goes first (round parity); workloads rotate by round. Not a random shuffle.\n'
	printf 'uname local %s\n' "$(uname -r)"
	if [ "$MODE" = local ]; then
		printf 'cterm binary %s\ncterm --version %s\n' "$BIN" "$("$BIN" --version)"
	else
		printf 'target %s\ntarget uname %s\ntarget cterm --version %s\n' "$HOST" "$(tx 'uname -r')" "$(tx "$TCT --version" 2>&1 || echo unavailable)"
		printf 'target daemon: %s\n' "${SESSION:+live (session $SESSION)}${FARDIR:+harness daemon in $FARDIR}"
	fi
	printf 'timer: clock_gettime(CLOCK_MONOTONIC) via perl syscall, ns resolution (Time::HiRes is not in perl-base)\n'
} >"$OUT/env.txt.part"
cat "$OUT/env.txt.part" "$OUT/env.txt" >"$OUT/env.new" 2>/dev/null && mv "$OUT/env.new" "$OUT/env.txt"
rm -f "$OUT/env.txt.part"
printf 'g4: run directory %s\n' "$OUT"; [ "$MODE" != local ] || printf 'g4: cterm binary %s\n' "$BIN"

# tpy ARGS...: run the helper on the target (session mode). pyl ARGS...: run it here on the viewer's PTY.
SEQ=0
# open_session SCRIPT: a windowed session on the harness daemon; sets SID (the daemon's id).
open_session() {
	SEQ=$((SEQ + 1))
	printf '%s\n' "$1" | txin "cat > $TD/s.$SEQ"
	mkfifo "$FIFO_DIR/h.$SEQ"
	if [ "$MODE" = remote ]; then
		ssh -o BatchMode=yes -- "$HOST" "env $TENV perl $PTY_T session $TD/run/cterm/daemon.sock $TD/s.$SEQ" <"$FIFO_DIR/h.$SEQ" >"$FIFO_DIR/o.$SEQ" 2>"$FIFO_DIR/e.$SEQ" &
	else
		env $TENV perl "$PTY_T" session "$TD/run/cterm/daemon.sock" "$TD/s.$SEQ" <"$FIFO_DIR/h.$SEQ" >"$FIFO_DIR/o.$SEQ" 2>"$FIFO_DIR/e.$SEQ" &
	fi
	HPID=$!; HPIDS="$HPIDS $HPID"
	exec 3>"$FIFO_DIR/h.$SEQ"
	i=0
	until grep -q '^pid ' "$FIFO_DIR/o.$SEQ" 2>/dev/null; do
		i=$((i + 1)); [ "$i" -le 100 ] || die "no session: $(cat "$FIFO_DIR/e.$SEQ")"
		sleep 0.1
	done
	SPID=$(sed -n 's/^pid //p' "$FIFO_DIR/o.$SEQ")
	SID=$(tx "$TCT ls" | while read -r id _ pid _; do [ "$pid" = "$SPID" ] && echo "$id"; done | head -1)
	[ -n "$SID" ] || die "session pid $SPID is not in cterm ls"
}
close_session() {
	exec 3>&-
	tx "$TCT kill $SID" >/dev/null 2>&1 || true
	i=0
	while kill -0 "$HPID" 2>/dev/null && [ "$i" -lt 30 ]; do i=$((i + 1)); sleep 0.1; done
	kill "$HPID" 2>/dev/null || true
}

if [ "$MODE" = remote ]; then
	VIEW="ssh -t -o BatchMode=yes -- $HOST env $TENV $TBIN attach"
else
	VIEW="env $TENV $TBIN attach"
fi
# pyl MODE ARGS... ; prints the helper's lines. A helper that dies or hangs fails the run loudly.
pyl() { timeout 180 perl "$PTYPL" "$@"; }
# rec LEG RUN KIND WARM: reads helper lines on stdin, appends `leg= run= kind= warm= key=value...` lines.
rec() { while read -r _w rest; do printf 'leg=%s run=%s kind=%s warm=%s %s\n' "$1" "$2" "$3" "$4" "$rest" >>"$OUT/$1.raw"; done; }
first_kind() { if [ $(($1 % 2)) -eq 0 ]; then echo "$2 $3"; else echo "$3 $2"; fi; }

leg_first() {
	printf 'g4: first-frame: %s runs after %s warm-up\n' "$RUNS" "$WARM"
	if [ -n "$SESSION" ]; then SID=$SESSION; MK=$MARKER; else open_session 'echo G4MARK; exec cat'; MK=G4MARK; fi
	r=0
	while [ "$r" -lt $((RUNS + WARM)) ]; do
		r=$((r + 1)); w=0; [ "$r" -le "$WARM" ] && w=1
		for k in $(first_kind "$r" cterm noise); do
			case $k in
			cterm) pyl first "$MK" 30 $VIEW "$SID" | rec first "$r" cterm "$w" ;;
			noise) pyl first G4MARK 30 sh -c 'echo G4MARK; exec sleep 5' | rec first "$r" noise "$w" ;;
			esac
		done
		[ "$MODE" != remote ] || pyl exit 30 ssh -o BatchMode=yes -- "$HOST" true | rec first "$r" handshake "$w"
	done
	[ -n "$SESSION" ] || close_session
}

leg_bytes() {
	if [ -n "$SESSION" ]; then
		printf 'g4: bytes: live session, idle observation only (%s s x %s runs)\n' "$BSECS" "$BRUNS"
		r=0
		while [ "$r" -lt "$BRUNS" ]; do r=$((r + 1)); pyl quiet "$MARKER" "$BSECS" $VIEW "$SESSION" | rec bytes "$r" idle 0; done
		return 0
	fi
	printf 'g4: bytes: %s runs per workload, %s s each\n' "$BRUNS" "$BSECS"
	r=0
	while [ "$r" -lt "$BRUNS" ]; do
		r=$((r + 1))
		case $((r % 3)) in 0) order='idle build redraw' ;; 1) order='build redraw idle' ;; *) order='redraw idle build' ;; esac
		for k in $order; do
			CF=$TD/count.$((SEQ + 1))
			open_session "echo G4READY; read x; perl $WL_T $k $BSECS $CF; exec cat"
			pyl bytes G4READY "$BSECS" $VIEW "$SID" | sed 's/$/ raw=0/' >"$FIFO_DIR/b.out"
			raw=$(tx "sed -n 's/^bytes //p' $CF" || echo 0)
			sed "s/ raw=0\$/ raw=${raw:-0}/" "$FIFO_DIR/b.out" | rec bytes "$r" "$k" 0
			close_session
		done
	done
}

leg_echo() {
	printf 'g4: echo: %s runs after %s warm-up, 20 keystrokes each\n' "$ERUNS" "$EWARM"
	if [ "$MODE" = remote ]; then
		if rtt=$(ping -c 20 -i 0.2 -q -- "$HOST" 2>/dev/null | sed -n 's/^rtt .* = //p'); then [ -n "$rtt" ] || rtt='not measured (ping unreachable or blocked)'; else rtt='not measured (no ping)'; fi
		printf 'ICMP ping min/avg/max/mdev %s\n' "$rtt" >"$OUT/rtt.txt"
	fi
	open_session 'echo G4READY; exec cat'
	r=0
	while [ "$r" -lt $((ERUNS + EWARM)) ]; do
		r=$((r + 1)); w=0; [ "$r" -le "$EWARM" ] && w=1
		for k in $(first_kind "$r" cterm noise); do
			case $k in
			cterm) pyl echo 20 G4READY $VIEW "$SID" | rec echo "$r" cterm "$w" ;;
			noise) pyl echo 20 - cat | rec echo "$r" noise "$w" ;;
			esac
		done
	done
	close_session
}

leg_stall() {
	printf 'g4: stall: %s runs, 5 s unread\n' "$SRUNS"
	r=0
	while [ "$r" -lt "$SRUNS" ]; do
		r=$((r + 1))
		open_session 'echo G4READY; read x; end=$(( $(date +%s) + 9 )); while [ $(date +%s) -lt $end ]; do seq 1 3000; done; echo G4FLOODEND; exec cat'
		pyl stall 15 5 G4READY G4FLOODEND $VIEW "$SID" | rec stall "$r" cterm 0
		close_session
	done
}

for l in $LEGS; do
	case $l in
	first-frame) leg_first ;;
	bytes) leg_bytes ;;
	echo) [ -n "$SESSION" ] || leg_echo ;;
	stall) [ -n "$SESSION" ] || leg_stall ;;
	summarize) ;;
	esac
done
cond end
perl "$HERE/summarize.pl" "$OUT" | tee "$OUT/summary.txt"
